import type * as React from "react"

import { cn } from "@/lib/utils"

/**
 * 页面主容器：固定宽度 + 左右竖线。
 * 宽度可通过 CSS 变量 --grid-width 覆盖（默认 48rem）。
 */
function GridContainer({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-container"
      className={cn(
        "mx-auto w-full max-w-[var(--grid-width,48rem)] border-x border-edge",
        className
      )}
      {...props}
    />
  )
}

/**
 * 一行内容：底部一条横跨整个屏幕的分隔线。
 * 放在 GridContainer 内使用。
 */
function GridSection({
  className,
  topLine = false,
  ...props
}: React.ComponentProps<"section"> & { topLine?: boolean }) {
  return (
    <section
      data-slot="grid-section"
      className={cn("screen-line-bottom", topLine && "screen-line-top", className)}
      {...props}
    />
  )
}

/**
 * 斜纹分隔带：全屏宽度的斜线纹理 + 底部横线。
 */
function GridSeparator({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      aria-hidden
      data-slot="grid-separator"
      className={cn("screen-line-bottom h-8 w-full", className)}
      {...props}
    >
      <div className="absolute inset-y-0 -left-[100vw] w-[200vw] bg-hatch" />
    </div>
  )
}

/**
 * 分栏：栏与栏之间用虚线分隔，窄屏自动堆叠。
 */
function GridColumns({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="grid-columns"
      className={cn(
        "grid grid-cols-1 divide-y divide-dashed divide-edge sm:grid-cols-2 sm:divide-x sm:divide-y-0",
        className
      )}
      {...props}
    />
  )
}

export { GridColumns, GridContainer, GridSection, GridSeparator }

"use client"

import { useMemo, useState } from "react"
import { cn } from "@/lib/utils"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"

export type Contribution = { date: string; count: number; level: number }
const levels = [
  "bg-foreground/5",
  "bg-foreground/20",
  "bg-foreground/40",
  "bg-foreground/60",
  "bg-foreground/80",
]
const dayMilliseconds = 86_400_000
const dateFormatter = new Intl.DateTimeFormat("zh-CN", {
  timeZone: "UTC",
  year: "numeric",
  month: "long",
  day: "numeric",
})

/** 按真实日期排列的贡献日历；空缺日期不冒充零贡献，数据表提供非颜色读取方式。 */
export function ContributionGraph({
  data,
  className,
}: {
  /** 过去一年的每日记录，顺序任意；只绘制最后一天往前 365 天 */
  data: readonly Contribution[]
  className?: string
}) {
  const [activeDate, setActiveDate] = useState<string | null>(null)
  const { weeks, entries } = useMemo(() => {
    const valid = data
      .filter(
        (entry) =>
          /^\d{4}-\d{2}-\d{2}$/.test(entry.date) &&
          Number.isFinite(Date.parse(entry.date)),
      )
      .toSorted((a, b) => a.date.localeCompare(b.date))
    if (!valid.length) return { weeks: [], entries: [] }
    const end = Date.parse(valid[valid.length - 1].date)
    const start = end - 364 * dayMilliseconds
    const firstSunday = start - new Date(start).getUTCDay() * dayMilliseconds
    const entries = valid.filter((entry) => Date.parse(entry.date) >= start)
    const byDate = new Map(entries.map((entry) => [entry.date, entry]))
    const weeks: {
      date: string
      day: Contribution | undefined
      month: string | null
    }[][] = []
    for (let stamp = firstSunday; stamp <= end; stamp += dayMilliseconds) {
      const date = new Date(stamp).toISOString().slice(0, 10)
      const weekIndex = Math.floor(
        (stamp - firstSunday) / (7 * dayMilliseconds),
      )
      const day = new Date(stamp)
      if (!weeks[weekIndex]) weeks[weekIndex] = []
      weeks[weekIndex].push({
        date,
        day: byDate.get(date),
        month: day.getUTCDate() === 1 ? `${day.getUTCMonth() + 1}月` : null,
      })
    }
    return { weeks, entries }
  }, [data])

  if (!entries.length)
    return (
      <p className="py-8 font-mono text-xs leading-6 text-muted-foreground">
        贡献日历暂未更新。下次构建时会自动重试获取数据。
      </p>
    )
  return (
    <div className={cn("min-w-0", className)}>
      <div
        role="region"
        aria-label="过去一年的 GitHub 贡献日历，可横向滚动；方向键查看相邻日期"
        tabIndex={0}
        className="overflow-x-auto rounded-sm pb-2 focus-visible:outline-2 focus-visible:outline-ring"
      >
        <div className="flex w-max gap-2 font-mono text-[10px] text-muted-foreground">
          <div
            aria-hidden="true"
            className="grid grid-rows-[18px_repeat(7,10px)] gap-[3px]"
          >
            <span />
            <span />
            <span>一</span>
            <span />
            <span>三</span>
            <span />
            <span>五</span>
            <span />
          </div>
          <TooltipProvider delay={100}>
            <div className="flex gap-[3px]">
              {weeks.map((week) => (
                <div
                  key={week[0].date}
                  className="grid w-[10px] grid-rows-[18px_repeat(7,10px)] gap-[3px]"
                >
                  <span
                    aria-hidden="true"
                    className="relative whitespace-nowrap"
                  >
                    {week.find((entry) => entry.month)?.month}
                  </span>
                  {week.map(({ date, day }) =>
                    day ? (
                      <Tooltip key={date}>
                        <TooltipTrigger
                          render={<button type="button" />}
                          tabIndex={
                            activeDate === date ||
                            (!activeDate && date === entries[0].date)
                              ? 0
                              : -1
                          }
                          onFocus={() => setActiveDate(date)}
                          onKeyDown={(event) => {
                            const offsets: Record<string, number> = {
                              ArrowDown: 1,
                              ArrowUp: -1,
                              ArrowLeft: -7,
                              ArrowRight: 7,
                            }
                            if (!(event.key in offsets)) return
                            event.preventDefault()
                            const position = entries.findIndex(
                              (entry) => entry.date === date,
                            )
                            const next =
                              entries[
                                Math.max(
                                  0,
                                  Math.min(
                                    entries.length - 1,
                                    position + offsets[event.key],
                                  ),
                                )
                              ]
                            const region =
                              event.currentTarget.closest('[role="region"]')
                            region
                              ?.querySelector<HTMLButtonElement>(
                                `[data-date="${next.date}"]`,
                              )
                              ?.focus()
                          }}
                          data-date={date}
                          aria-label={`${dateFormatter.format(new Date(date))}：${day.count} 次贡献`}
                          className={cn(
                            "size-[10px] rounded-[2px] focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
                            levels[
                              Math.max(0, Math.min(4, Math.floor(day.level)))
                            ] ?? levels[0],
                          )}
                        />
                        <TooltipContent>
                          {dateFormatter.format(new Date(date))} ·{" "}
                          {new Intl.NumberFormat("zh-CN").format(day.count)}{" "}
                          次贡献
                        </TooltipContent>
                      </Tooltip>
                    ) : (
                      <span
                        key={date}
                        aria-hidden="true"
                        className="size-[10px]"
                      />
                    ),
                  )}
                </div>
              ))}
            </div>
          </TooltipProvider>
        </div>
      </div>
      <div
        aria-label="贡献数量由少到多"
        className="mt-3 flex items-center justify-end gap-1.5 font-mono text-[10px] text-muted-foreground"
      >
        <span>少</span>
        {levels.map((level) => (
          <span
            key={level}
            aria-hidden="true"
            className={cn("size-2.5 rounded-[2px]", level)}
          />
        ))}
        <span>多</span>
      </div>
      <details className="mt-2 text-xs text-muted-foreground">
        <summary className="w-fit cursor-pointer rounded py-1 hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring">
          查看每日贡献数据
        </summary>
        <div className="mt-2 max-h-48 overflow-auto">
          <table className="w-full text-left font-mono tabular-nums">
            <caption className="sr-only">过去一年的每日贡献记录</caption>
            <thead>
              <tr>
                <th scope="col" className="py-2 font-normal">
                  日期
                </th>
                <th scope="col" className="py-2 text-right font-normal">
                  贡献次数
                </th>
              </tr>
            </thead>
            <tbody>
              {entries.map((day) => (
                <tr key={day.date}>
                  <th scope="row" className="py-1 font-normal">
                    {day.date}
                  </th>
                  <td className="text-right">
                    {new Intl.NumberFormat("zh-CN").format(day.count)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </details>
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"

/** 以指定 IANA 时区显示时间，并比较访客当前的时区偏移。 */
export function LocalTime({ timeZone }: {
  /** IANA 时区名，例如 `Asia/Shanghai`，不支持 `+08:00` 这类固定偏移 */
  timeZone: string
}) {
  const [now, setNow] = useState<Date | null>(null)
  useEffect(() => {
    const update = () => setNow(new Date())
    const first = window.setTimeout(update, 0)
    const timer = window.setInterval(update, 1000)
    return () => {
      window.clearTimeout(first)
      window.clearInterval(timer)
    }
  }, [])

  if (!now)
    return (
      <span className="tabular-nums">
        --:--:-- <span className="text-muted-foreground">{"// 当地时间"}</span>
      </span>
    )
  const formatter = new Intl.DateTimeFormat("zh-CN", {
    timeZone,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  })
  const zone =
    new Intl.DateTimeFormat("en-US", { timeZone, timeZoneName: "longOffset" })
      .formatToParts(now)
      .find((part) => part.type === "timeZoneName")?.value ?? "GMT"
  const offset = zone.match(/GMT([+-])(\d{2}):(\d{2})/)
  const targetMinutes = offset
    ? (Number(offset[2]) * 60 + Number(offset[3])) *
      (offset[1] === "+" ? 1 : -1)
    : 0
  const difference = (targetMinutes + now.getTimezoneOffset()) / 60
  const comparison =
    difference === 0
      ? "与你同一时间"
      : `${difference > 0 ? "早" : "晚"} ${new Intl.NumberFormat("zh-CN", { maximumFractionDigits: 2 }).format(Math.abs(difference))} 小时`
  return (
    <span className="tabular-nums">
      <time dateTime={now.toISOString()}>{formatter.format(now)}</time>{" "}
      <span className="text-muted-foreground">
        {"// "}
        {comparison}
      </span>
    </span>
  )
}

"use client"

import { useEffect, useState } from "react"

/** 根据访客当地时间问候，首屏使用一致的静态文案以避免水合差异。 */
export function Greeting({
  fallback = "你好",
  suffix = "，很高兴在这里遇见你。",
}: {
  /** 首屏与挂载前显示的静态文案，需保持中性以避免水合差异 */
  fallback?: string
  /** 问候语之后拼接的文本，默认带一个逗号 */
  suffix?: string
}) {
  const [greeting, setGreeting] = useState(fallback)
  useEffect(() => {
    const update = () => {
      const hour = new Date().getHours()
      setGreeting(
        hour >= 5 && hour < 11
          ? "早上好"
          : hour >= 11 && hour < 14
            ? "中午好"
            : hour >= 14 && hour < 18
              ? "下午好"
              : "晚上好",
      )
    }
    const first = window.setTimeout(update, 0)
    const timer = window.setInterval(update, 60_000)
    return () => {
      window.clearTimeout(first)
      window.clearInterval(timer)
    }
  }, [])
  return (
    <>
      {greeting}
      {suffix}
    </>
  )
}

import type { ComponentProps, ReactNode } from "react"
import { cn } from "@/lib/utils"

/** 有明确名称和键盘焦点的图标链接方块。 */
export function IconLink({
  label,
  children,
  className,
  ...props
}: ComponentProps<"a"> & {
  /** 同时作为 aria-label 与 title 的可读名称，必填 */
  label: string
  children: ReactNode
}) {
  return (
    <a
      aria-label={label}
      title={label}
      className={cn(
        "inline-flex size-11 items-center justify-center rounded-md border border-edge bg-muted/30 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring [&_svg]:size-5",
        className,
      )}
      {...props}
    >
      <span aria-hidden="true">{children}</span>
    </a>
  )
}
